117:func mergeShipHotLaneMembership(state *RealtimeSessionState, world WorldWireFullPacket) ShipHotLaneProjection {
118:	current := projectShipHotLane(world)
119:	previous, ok := state.BaselineProjection(LaneShips)
120:	if !ok {
121:		return current
122:	}
123:	typed, ok := previous.(ShipHotLaneProjection)
124:	if !ok {
125:		return current
126:	}
127:	previousByID := make(map[string]WorldShipWireRecord, len(typed.Records))
128:	for _, record := range typed.Records {
129:		previousByID[record.ID] = record
130:	}
131:	for index, record := range current.Records {
132:		if existing, ok := previousByID[record.ID]; ok {
133:			current.Records[index] = existing
134:		}
135:	}
136:	return current
137:}
