9:func buildOverlayLaneCandidates(snapshot game.GameplayPresentationSnapshot, state RealtimeSessionState) ([]RealtimeLaneCandidate, error) {
10:	candidates := make([]RealtimeLaneCandidate, 0, 1)
11:
12:	overlayState, overlaySynced := state.LaneState(LaneOverlay)
13:	overlayReady := state.LaneBaselineReady(LaneOverlay)
14:	overlaySequence := NextLaneSequence(overlayState, overlaySynced)
15:	overlayFull := BuildOverlayFullPacket(snapshot, state.ReceiverID, overlaySequence)
16:	quantizedOverlayFull, err := quantizeOverlayFullPacket(overlayFull)
17:	if err != nil {
18:		return nil, fmt.Errorf("quantize overlay full packet: %w", err)
19:	}
20:	overlayProjection, overlayHasProjection := state.BaselineProjection(LaneOverlay)
21:	overlayCanUseProjection := overlayReady && overlaySynced && overlayState.IsFinalChunk && overlayState.BaselineID != "" && overlayHasProjection
22:	if !overlayCanUseProjection {
23:		candidates = append(candidates, mustRealtimeLaneCandidate(quantizedOverlayFull, quantizedOverlayFull))
24:	} else {
25:		previousOverlayFull, ok := overlayProjection.(OverlayWireFullPacket)
26:		if !ok {
27:			candidates = append(candidates, mustRealtimeLaneCandidate(quantizedOverlayFull, quantizedOverlayFull))
28:		} else {
29:			if !OverlayWirePayloadChanged(previousOverlayFull, quantizedOverlayFull) {
30:				// No overlay candidate when the projection is unchanged.
31:			} else {
32:				overlayDelta := BuildOverlayWireDeltaPacket(previousOverlayFull, quantizedOverlayFull)
33:				if OverlayWireDeltaHasChanges(overlayDelta) {
34:					chainedOverlayProjection := quantizedOverlayFull
35:					chainedOverlayProjection.Metadata = overlayDelta.Metadata
36:					candidates = append(candidates, mustRealtimeLaneCandidate(overlayDelta, chainedOverlayProjection))
37:				}
38:			}
39:		}
40:	}
41:
42:	return candidates, nil
43:}

