9:func buildSessionLaneCandidates(snapshot game.GameplayPresentationSnapshot, state RealtimeSessionState) ([]RealtimeLaneCandidate, error) {
10:	candidates := make([]RealtimeLaneCandidate, 0, 1)
11:
12:	sessionStateLane, sessionSynced := state.LaneState(LaneSession)
13:	sessionReady := state.LaneBaselineReady(LaneSession)
14:	sessionSequence := NextLaneSequence(sessionStateLane, sessionSynced)
15:	sessionFull := BuildSessionFullPacket(snapshot, sessionSequence)
16:	quantizedSessionFull, err := quantizeSessionFullPacket(sessionFull)
17:	if err != nil {
18:		return nil, fmt.Errorf("quantize session full packet: %w", err)
19:	}
20:	sessionProjection, sessionHasProjection := state.BaselineProjection(LaneSession)
21:	sessionCanUseProjection := sessionReady && sessionSynced && sessionStateLane.IsFinalChunk && sessionStateLane.BaselineID != "" && sessionHasProjection
22:	if !sessionCanUseProjection {
23:		candidates = append(candidates, mustRealtimeLaneCandidate(quantizedSessionFull, quantizedSessionFull))
24:	} else {
25:		previousSessionFull, ok := sessionProjection.(SessionWireFullPacket)
26:		if !ok {
27:			candidates = append(candidates, mustRealtimeLaneCandidate(quantizedSessionFull, quantizedSessionFull))
28:		} else {
29:			if !SessionWirePayloadChanged(previousSessionFull, quantizedSessionFull) {
30:				// No session candidate when the projection is unchanged.
31:			} else {
32:				sessionDelta := BuildSessionWireDeltaPacket(previousSessionFull, quantizedSessionFull)
33:				if SessionWireDeltaHasChanges(sessionDelta) {
34:					chainedSessionProjection := quantizedSessionFull
35:					chainedSessionProjection.Metadata = sessionDelta.Metadata
36:					candidates = append(candidates, mustRealtimeLaneCandidate(sessionDelta, chainedSessionProjection))
37:				}
38:			}
39:		}
40:	}
41:
42:	return candidates, nil
43:}

