9:func buildWorldLaneCandidates(snapshot game.GameplayPresentationSnapshot, state RealtimeSessionState, sessionState *RealtimeSessionState) ([]RealtimeLaneCandidate, error) {
10:	candidates := make([]RealtimeLaneCandidate, 0, 7)
11:
12:	worldState, worldSynced := state.LaneState(LaneWorld)
13:	worldReady := state.LaneBaselineReady(LaneWorld)
14:	worldSequence := NextLaneSequence(worldState, worldSynced)
15:	worldFull := BuildWorldFullPacket(snapshot, worldSequence)
16:	currentWorld, err := quantizeWorldFullPacket(worldFull)
17:	if err != nil {
18:		return nil, fmt.Errorf("quantize world full packet: %w", err)
19:	}
20:
21:	storedWorld, worldHasProjection := state.BaselineProjection(LaneWorld)
22:	worldCanUseProjection := worldReady && worldSynced && worldState.IsFinalChunk && worldState.BaselineID != "" && worldHasProjection
23:	if !worldCanUseProjection {
24:		return append(candidates, mustRealtimeLaneCandidate(currentWorld, currentWorld)), nil
25:	}
26:	previousWorld, ok := storedWorld.(WorldWireFullPacket)
27:	if !ok {
28:		return append(candidates, mustRealtimeLaneCandidate(currentWorld, currentWorld)), nil
29:	}
30:
31:	if WorldWirePayloadChanged(previousWorld, currentWorld) {
32:		candidates = append(candidates, buildReliableWorldCandidates(previousWorld, currentWorld, state)...)
33:	}
34:
35:	hotCandidates, cohortState := buildIndependentHotLaneCandidates(previousWorld, currentWorld, state)
36:	candidates = append(candidates, hotCandidates...)
37:	if sessionState != nil {
38:		sessionState.HotLaneCohorts = cohortState
39:	}
40:	return candidates, nil
41:}
