43:func buildReliableWorldCandidates(previousWorld WorldWireFullPacket, currentWorld WorldWireFullPacket, state RealtimeSessionState) []RealtimeLaneCandidate {
44:	worldDelta := BuildWorldWireDeltaPacket(previousWorld, currentWorld)
45:	_, shipReliableUpdates := partitionShipUpdates(worldDelta.Ships.Updates)
46:	worldDelta.Ships.Updates = shipReliableUpdates
47:	worldDelta.Asteroids.Updates = nil
48:	worldDelta.Bullets.Updates = nil
49:
50:	shipLifecyclePresent := len(worldDelta.Ships.Creates) > 0 || len(worldDelta.Ships.Updates) > 0 || len(worldDelta.Ships.Deletes) > 0
51:	asteroidLifecyclePresent := len(worldDelta.Asteroids.Creates) > 0 || len(worldDelta.Asteroids.Deletes) > 0
52:	bulletLifecyclePresent := len(worldDelta.Bullets.Creates) > 0 || len(worldDelta.Bullets.Deletes) > 0
53:	projectionAdvanceRequired := WorldWireDeltaHasChanges(worldDelta)
54:	if !projectionAdvanceRequired {
55:		return nil
56:	}
57:
58:	candidates := make([]RealtimeLaneCandidate, 0, 4)
59:	if shipLifecyclePresent {
60:		if candidate, ok := buildShipLifecycleCandidate(worldDelta, state); ok {
61:			candidates = append(candidates, candidate)
62:			worldDelta.Ships.Creates = nil
63:			worldDelta.Ships.Updates = nil
64:			worldDelta.Ships.Deletes = nil
65:		}
66:	}
67:	if asteroidLifecyclePresent {
68:		if candidate, ok := buildAsteroidLifecycleCandidate(worldDelta, state); ok {
69:			candidates = append(candidates, candidate)
70:			worldDelta.Asteroids.Creates = nil
71:			worldDelta.Asteroids.Deletes = nil
72:		}
73:	}
74:	if bulletLifecyclePresent {
75:		if candidate, ok := buildBulletLifecycleCandidate(worldDelta, state); ok {
76:			candidates = append(candidates, candidate)
77:			worldDelta.Bullets.Creates = nil
78:			worldDelta.Bullets.Deletes = nil
79:		}
80:	}
81:
82:	chainedWorldProjection := currentWorld
83:	chainedWorldProjection.Metadata = worldDelta.Metadata
84:	candidates = append(candidates, mustRealtimeLaneCandidate(worldDelta, chainedWorldProjection))
85:	return candidates
86:}
