132:func encodedMetricPackets(result ActiveRealtimeResult) []EncodedRealtimeLanePacket {
133:	if len(result.EncodedLanePackets) > 0 {
134:		return result.EncodedLanePackets
135:	}
136:
137:	if len(result.SelectedCandidates) == 0 || len(result.EncodedBytes) == 0 {
138:		return nil
139:	}
140:
141:	packets := make([]EncodedRealtimeLanePacket, 0, len(result.SelectedCandidates))
142:	for _, candidate := range result.SelectedCandidates {
143:		encodedBytes := result.EncodedBytes[candidate.Lane()]
144:		if encodedBytes <= 0 {
145:			continue
146:		}
147:		packets = append(packets, EncodedRealtimeLanePacket{
148:			Candidate:    candidate,
149:			EncodedBytes: encodedBytes,
150:		})
151:	}
152:	return packets
153:}
