3:func deliveryClassForCandidate(candidate RealtimeLaneCandidate) DeliveryClass {
4:	lane, kind := candidate.Lane(), candidate.Kind()
5:	switch kind {
6:	case RealtimeLaneCandidateKindEventBatch:
7:		return DeliveryClassEventOnce
8:	case RealtimeLaneCandidateKindDelta:
9:		switch lane {
10:		case LaneSession, LaneWorld:
11:			return DeliveryClassRequired
12:		case LaneOverlay, LaneShips, LaneAsteroids, LaneBullets:
13:			return DeliveryClassHotSupersedable
14:		case LaneShipsLifecycle, LaneAsteroidsLifecycle, LaneBulletsLifecycle:
15:			return DeliveryClassRequired
16:		}
17:	default:
18:		return DeliveryClassRequired
19:	}
20:
21:	return DeliveryClassRequired
22:}
23:
24:func priorityForCandidate(candidate RealtimeLaneCandidate) Priority {
25:	lane, kind := candidate.Lane(), candidate.Kind()
26:	switch kind {
27:	case RealtimeLaneCandidateKindEventBatch, RealtimeLaneCandidateKindFull:
28:		return PriorityCritical
29:	case RealtimeLaneCandidateKindDelta:
30:		switch lane {
31:		case LaneWorld:
32:			return PriorityCritical
33:		case LaneSession:
34:			return PriorityMedium
35:		case LaneOverlay, LaneShips, LaneAsteroids, LaneBullets:
36:			return PriorityHigh
37:		case LaneShipsLifecycle, LaneAsteroidsLifecycle, LaneBulletsLifecycle:
38:			return PriorityCritical
39:		}
40:	}
41:
42:	return PriorityCritical
43:}
