45:func scheduleRecordForCandidate(candidateIndex int, candidate RealtimeLaneCandidate) ScheduleRecord {
46:	packetFamily := candidate.PacketFamily()
47:	record := ScheduleRecord{
48:		Lane:           candidate.Lane(),
49:		CandidateIndex: candidateIndex,
50:		PacketFamily:   packetFamily,
51:		RecordKind:     string(candidate.Kind()),
52:		Priority:       priorityForCandidate(candidate),
53:		DeliveryClass:  deliveryClassForCandidate(candidate),
54:		EstimatedBytes: EstimatePacketBytes(packetFamily, 1, 0),
55:		ChunkCount:     1,
56:		IsFinalChunk:   true,
57:		PayloadRef:     candidate.Payload,
58:	}
59:	if metadata, ok := candidate.Metadata(); ok {
60:		record.ChunkIndex = metadata.ChunkIndex
61:		record.ChunkCount = metadata.ChunkCount
62:		record.IsFinalChunk = metadata.IsFinalChunk
63:	}
64:	return record
65:}
