67:func CandidateProjection(candidate RealtimeLaneCandidate) (any, bool) {
68:	if candidate.Kind() == RealtimeLaneCandidateKindEventBatch {
69:		return nil, false
70:	}
71:	if candidate.Projection == nil {
72:		return nil, false
73:	}
74:	return candidate.Projection, true
