12:func SortOrderedRecordKeys(keys []OrderedRecordKey) {
13:	sort.SliceStable(keys, func(i, j int) bool {
14:		left := keys[i]
15:		right := keys[j]
16:		if left.Lane != right.Lane {
17:			return left.Lane < right.Lane
18:		}
19:		if left.Family != right.Family {
20:			return left.Family < right.Family
21:		}
22:		if left.Kind != right.Kind {
23:			return left.Kind < right.Kind
24:		}
25:		return left.ID < right.ID
26:	})
27:}

