396:func (p *WebRTCTransport) BufferedAmountForLane(lane string) (uint64, bool) {
397:	p.mu.RLock()
398:	channel, ok := p.channels[lane]
399:	p.mu.RUnlock()
400:	if !ok || channel == nil {
401:		return 0, false
402:	}
403:	return channel.BufferedAmount(), true
404:}
405:
406:func channelWouldExceedBufferedAmount(channel webRTCDataChannel, payloadBytes int) bool {
407:	if channel == nil {
408:		return false
409:	}
410:	buffered := channel.BufferedAmount()
411:	if buffered >= webRTCMaxBufferedAmountBytes {
412:		return true
413:	}
414:	return uint64(payloadBytes) > webRTCMaxBufferedAmountBytes-buffered
415:}
