420:	p.mu.RUnlock()
421:	if !ok || channel == nil {
422:		return nil, errors.New("webrtc tooling lane channel is not configured")
423:	}
424:	if channel.ReadyState() != webrtc.DataChannelStateOpen {
425:		return nil, errors.New("webrtc tooling lane channel is not open")
426:	}
427:	return channel, nil
428:}
