10:func tickSessionGameplayLifecycle(session *webSocketSession, done <-chan struct{}) {
11:	ticker := time.NewTicker(time.Second / time.Duration(constants.ServerTickRate))
12:	defer ticker.Stop()
13:
14:	for {
15:		select {
16:		case <-done:
17:			return
18:		case <-ticker.C:
19:			context := session.sessionContext()
20:			if context.Room == nil || context.GamePlayerID == "" {
21:				continue
22:			}
23:
24:			if rooms.TickRoomGameOverLifecycle(context.Room, BroadcastRoomSnapshot) {
25:				rooms.ReportResolvedMatchResultOnce(context.Room, session.matchResultReporter)
26:			}
27:		}
28:	}
