528:func wireMetadataPacket(packetType string, metadata Metadata) map[string]any {
529:	wire := map[string]any{
530:		"type":             packetType,
531:		"sequence":         metadata.Sequence,
532:		"server_sent_msec": metadata.ServerSentMsec,
533:	}
534:	if !isRuntimePacketType(packetType) {
535:		wire["lane"] = string(metadata.Lane)
536:		wire["baseline_id"] = metadata.BaselineID
537:		wire["snapshot_id"] = metadata.SnapshotID
538:		wire["snapshot_kind"] = string(metadata.SnapshotKind)
539:		wire["chunk_index"] = metadata.ChunkIndex
540:		wire["chunk_count"] = metadata.ChunkCount
541:		wire["is_final_chunk"] = metadata.IsFinalChunk
542:		return wire
543:	}
544:
545:	if metadata.SnapshotKind == SnapshotKind("delta") {
546:		if baselineSequence, ok := runtimeBaselineSequence(metadata.Lane, metadata.BaselineID); ok {
547:			wire["baseline_sequence"] = baselineSequence
548:		} else if metadata.BaselineID != "" {
549:			wire["baseline_id"] = metadata.BaselineID
550:		}
551:	} else if metadata.BaselineID != "" && !isRuntimeGeneratedFullBaseline(metadata) {
552:		wire["baseline_id"] = metadata.BaselineID
553:	}
554:
555:	if metadata.ChunkCount > 1 {
556:		wire["chunk_index"] = metadata.ChunkIndex
557:		wire["chunk_count"] = metadata.ChunkCount
558:		if metadata.IsFinalChunk {
559:			wire["is_final_chunk"] = true
560:		}
561:	}
562:	return wire
563:}
564:
565:func isRuntimePacketType(packetType string) bool {
566:	switch packetType {
567:	case PacketFamilyWorldFull, PacketTypeWorldDelta, PacketFamilyShipDelta, PacketFamilyOverlayFull, PacketTypeOverlayDelta,
568:		PacketFamilySessionFull, PacketTypeSessionDelta, PacketFamilyAsteroidDelta, PacketFamilyBulletDelta:
569:		return true
570:	default:
571:		return false
572:	}
573:}
574:
575:func runtimeBaselineSequence(lane Lane, baselineID string) (int, bool) {
576:	prefix := string(lane) + "-baseline-"
577:	if !strings.HasPrefix(baselineID, prefix) {
578:		return 0, false
579:	}
580:	sequence, err := strconv.Atoi(strings.TrimPrefix(baselineID, prefix))
581:	if err != nil {
582:		return 0, false
583:	}
584:	return sequence, true
585:}
586:
587:func isRuntimeGeneratedFullBaseline(metadata Metadata) bool {
588:	if metadata.BaselineID == "" {
589:		return true
590:	}
591:	sequence, ok := runtimeBaselineSequence(metadata.Lane, metadata.BaselineID)
592:	if !ok {
593:		return false
594:	}
595:	return sequence == metadata.Sequence
596:}

