137:func CompareLaneRecords[T any](previous []T, current []T, recordID func(T) string, equal func(T, T) bool) RecordDelta[T] {
138:	previousByID := make(map[string]T, len(previous))
139:	for _, record := range previous {
140:		previousByID[recordID(record)] = record
141:	}
142:
143:	currentByID := make(map[string]T, len(current))
144:	currentIDs := make([]string, 0, len(current))
145:	for _, record := range current {
146:		id := recordID(record)
147:		currentByID[id] = record
148:		currentIDs = append(currentIDs, id)
149:	}
150:	sort.Strings(currentIDs)
151:
152:	previousIDs := make([]string, 0, len(previous))
153:	for _, record := range previous {
154:		previousIDs = append(previousIDs, recordID(record))
155:	}
156:	sort.Strings(previousIDs)
157:
158:	delta := RecordDelta[T]{}
159:
160:	for _, id := range currentIDs {
161:		currentRecord := currentByID[id]
162:		previousRecord, ok := previousByID[id]
163:		if !ok {
164:			delta.Creates = append(delta.Creates, currentRecord)
165:			continue
166:		}
167:		if !equal(previousRecord, currentRecord) {
168:			delta.Updates = append(delta.Updates, currentRecord)
169:		}
170:	}
171:
172:	for _, id := range previousIDs {
173:		if _, ok := currentByID[id]; !ok {
174:			delta.Deletes = append(delta.Deletes, id)
175:		}
176:	}
177:
178:	return delta
179:}
