29:func SplitWorldHotUpdates(worldDelta WorldWireDeltaPacket, cohortState HotLaneCohortState, _ HotLaneOffloadPolicy) HotLaneSplitResult {
30:	cohortState.EnsureInitialized()
31:
32:	shipHotUpdates, shipReliableUpdates := partitionShipUpdates(worldDelta.Ships.Updates)
33:	shipActive := activeUpdateIDsFromWireRecords(shipHotUpdates)
34:	asteroidActive := activeUpdateIDsFromWireRecords(worldDelta.Asteroids.Updates)
35:	bulletActive := activeUpdateIDsFromWireRecords(worldDelta.Bullets.Updates)
36:	shipIDs := sortedHotLaneUpdateIDs(shipActive)
37:	asteroidIDs := sortedHotLaneUpdateIDs(asteroidActive)
38:	bulletIDs := sortedHotLaneUpdateIDs(bulletActive)
39:
40:	result := HotLaneSplitResult{
41:		WorldDelta:       worldDelta,
42:		CohortState:      cohortState,
43:		ShipMode:         HotLaneModeInline,
44:		AsteroidMode:     HotLaneModeInline,
45:		BulletMode:       HotLaneModeInline,
46:		ShipHotCount:     len(shipIDs),
47:		AsteroidHotCount: len(asteroidIDs),
48:		BulletHotCount:   len(bulletIDs),
49:	}
50:	result.WorldHotCount = result.ShipHotCount + result.AsteroidHotCount + result.BulletHotCount
51:
52:	result.WorldDelta.Ships.Updates = shipReliableUpdates
53:	if len(shipIDs) > 0 {
54:		assignHotRoutesWithOverride(result.CohortState.ShipRoutes, shipIDs, HotUpdateRouteShips)
55:		result.ShipMode = HotLaneModeFullOwned60Hz
56:		result.CohortState.ShipMode = result.ShipMode
57:		result.ShipOffloaded = len(shipIDs)
58:		metadata := worldDelta.Metadata
59:		metadata.Lane = LaneShips
60:		metadata.SnapshotKind = SnapshotKind("delta")
61:		metadata = metadata.WithChunk(0, 1)
62:		result.ShipDelta = &ShipWireDeltaPacket{
63:			Type:        PacketFamilyShipDelta,
64:			Metadata:    metadata,
65:			ShipUpdates: shipHotUpdates,
66:		}
67:	}
68:	if len(asteroidIDs) > 0 {
69:		assignHotRoutesWithOverride(result.CohortState.AsteroidRoutes, asteroidIDs, HotUpdateRouteAsteroids)
70:		result.WorldDelta.Asteroids.Updates = nil
71:		result.AsteroidMode = HotLaneModeFullOwned60Hz
72:		result.CohortState.AsteroidMode = result.AsteroidMode
73:		result.AsteroidOffloaded = len(asteroidIDs)
74:		metadata := worldDelta.Metadata
75:		metadata.Lane = LaneAsteroids
76:		metadata.SnapshotKind = SnapshotKind("delta")
77:		metadata = metadata.WithChunk(0, 1)
78:		result.AsteroidDelta = &AsteroidWireDeltaPacket{
79:			Type:            PacketFamilyAsteroidDelta,
80:			Metadata:        metadata,
81:			AsteroidUpdates: worldDelta.Asteroids.Updates,
82:		}
83:	}
84:	if len(bulletIDs) > 0 {
85:		assignHotRoutesWithOverride(result.CohortState.BulletRoutes, bulletIDs, HotUpdateRouteBullets)
86:		result.WorldDelta.Bullets.Updates = nil
87:		result.BulletMode = HotLaneModeFullOwned60Hz
88:		result.CohortState.BulletMode = result.BulletMode
89:		result.BulletOffloaded = len(bulletIDs)
90:		metadata := worldDelta.Metadata
91:		metadata.Lane = LaneBullets
92:		metadata.SnapshotKind = SnapshotKind("delta")
93:		metadata = metadata.WithChunk(0, 1)
94:		result.BulletDelta = &BulletWireDeltaPacket{
95:			Type:          PacketFamilyBulletDelta,
96:			Metadata:      metadata,
97:			BulletUpdates: worldDelta.Bullets.Updates,
98:		}
99:	}
100:	result.CohortState.RemoveMissingShips(shipActive)
101:	result.CohortState.RemoveMissingAsteroids(asteroidActive)
102:	result.CohortState.RemoveMissingBullets(bulletActive)
103:	return result
104:}
