106:var shipHotUpdateKeys = map[string]struct{}{
107:	"x":         {},
108:	"y":         {},
109:	"rotation":  {},
110:	"thrusting": {},
111:}
112:
113:func partitionShipUpdates(records []map[string]any) ([]map[string]any, []map[string]any) {
114:	hot := make([]map[string]any, 0, len(records))
115:	reliable := make([]map[string]any, 0, len(records))
116:	for _, record := range records {
117:		id := asString(record["id"])
118:		if id == "" {
119:			continue
120:		}
121:		hotRecord := map[string]any{"id": id}
122:		reliableRecord := map[string]any{"id": id}
123:		for key, value := range record {
124:			if key == "id" {
125:				continue
126:			}
127:			if _, ok := shipHotUpdateKeys[key]; ok {
128:				hotRecord[key] = value
129:				continue
130:			}
131:			reliableRecord[key] = value
132:		}
133:		if len(hotRecord) > 1 {
134:			hot = append(hot, hotRecord)
135:		}
136:		if len(reliableRecord) > 1 {
137:			reliable = append(reliable, reliableRecord)
138:		}
139:	}
140:	return hot, reliable
141:}
142:
143:func sortedHotLaneUpdateIDs(active map[string]bool) hotLaneSortedUpdateIDs {
144:	ids := make(hotLaneSortedUpdateIDs, 0, len(active))
145:	for id := range active {
146:		ids = append(ids, hotLaneSortedUpdateID{ID: id})
147:	}
148:	sort.Slice(ids, func(i, j int) bool {
149:		return ids[i].ID < ids[j].ID
150:	})
151:	return ids
152:}
153:
154:func assignHotRoutesWithOverride(routes map[string]HotUpdateRoute, ids hotLaneSortedUpdateIDs, route HotUpdateRoute) {
155:	for _, item := range ids {
156:		if existing, exists := routes[item.ID]; exists && existing == route {
157:			continue
158:		}
159:		routes[item.ID] = route
160:	}
161:}
162:
163:func activeUpdateIDsFromWireRecords(records []map[string]any) map[string]bool {
164:	active := make(map[string]bool, len(records))
165:	for _, record := range records {
166:		id := asString(record["id"])
167:		if id == "" {
168:			continue
169:		}
170:		active[id] = true
171:	}
172:	return active
173:}

