565:func isRuntimePacketType(packetType string) bool {
566:	switch packetType {
567:	case PacketFamilyWorldFull, PacketTypeWorldDelta, PacketFamilyShipDelta, PacketFamilyOverlayFull, PacketTypeOverlayDelta,
568:		PacketFamilySessionFull, PacketTypeSessionDelta, PacketFamilyAsteroidDelta, PacketFamilyBulletDelta:
569:		return true
570:	default:
571:		return false
572:	}
