575:func runtimeBaselineSequence(lane Lane, baselineID string) (int, bool) {
576:	prefix := string(lane) + "-baseline-"
577:	if !strings.HasPrefix(baselineID, prefix) {
578:		return 0, false
579:	}
580:	sequence, err := strconv.Atoi(strings.TrimPrefix(baselineID, prefix))
581:	if err != nil {
582:		return 0, false
583:	}
584:	return sequence, true
585:}
